def transform(grid):
    h, w = len(grid), len(grid[0])
    rbar = next(r for r,row in enumerate(grid) if all(v == 3 for v in row))
    cbar = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r != rbar and c != cbar:
                out[r][c] = 0
    return out
